UPDATE schemes SET `content`='<p>Sukanya Samriddhi Yojana (SSY) is a government-backed savings scheme for girl children. It offers one of the highest interest rates among small savings schemes.</p>
<h3>Key Features</h3>
<ul>
<li>Interest rate: 8.2% per annum (compounded annually)</li>
<li>Minimum deposit: ₹250 per year</li>
