UPDATE schemes SET `content`='<p>Pradhan Mantri Matru Vandana Yojana (PMMVY) provides cash incentive of ₹5,000 to pregnant and lactating mothers for first living child. It compensates for wage loss during pregnancy and after childbirth.</p>
<h3>Benefits</h3>
<ul>
<li>₹5,000 in 3 installments</li>
<li>Cash transfer directly to bank/post office account</li>
<li>First installment: ₹1,000 after registration</li>
<li>Second installment: ₹2,000 after 6 months of pregnancy</li>
<li>Third installment: ₹2,000 after child birth and immunization</li>
</ul>', `eligibility`='All pregnant and lactating mothers for first living child (excluding girls born under BBBP). Must be 19+ years. Must have registered at health facility.', `benefits`='₹5,000 cash incentive in 3 installments, direct bank transfer.', `application_process`='1. Register at nearest Health/Facility/ASHA\n2. Submit application with Aadhaar and bank details\n3. First installment after registration\n4. Second installment after 6 months\n5. Third installment after delivery', `required_documents`='Aadhaar Card, Bank account details, Child birth registration, Health facility registration' WHERE `slug`='pm-matru-vandana-yojana';
UPDATE schemes SET `content`='<p>Digital India is a flagship programme of the Government of India to transform India into a digitally empowered society and knowledge economy. Launched on 1st July 2015.</p>
<h3>Three Core Components</h3>
<ul>
<li><strong>Digital Infrastructure:</strong> Broadband highways, universal access to mobile connectivity, public internet access programme</li>
<li><strong>Governance & Services:</strong> e-Governance, e-Kranti, information for all</li>
<li><strong>Digital Empowerment:</strong> Digital literacy, digital resources, industry digitization</li>
</ul>
<h3>Key Schemes Under Digital India</h3>
<ul>
<li>BharatNet (broadband to villages)</li>
<li>DigiLocker (digital document storage)</li>
<li>e-Sign (digital signatures)</li>
<li>UMANG (unified government services app)</li>
</ul>', `eligibility`='All Indian citizens. Various sub-schemes have specific eligibility.', `benefits`='Digital infrastructure access, e-governance services, digital literacy, DigiLocker, UMANG app.', `application_process`='Varies by sub-scheme. UMANG app available on Google Play and App Store. DigiLocker at digilocker.gov.in.', `required_documents`='Aadhaar Card for most services' WHERE `slug`='digital-india-programme';
UPDATE schemes SET `content`='<p>Swachh Bharat Mission (SBM) was launched on 2nd October 2014 to achieve universal sanitation coverage. It has two components: Urban and Rural.</p>
<h3>SBM - Gramin (Rural)</h3>
<ul>
<li>Individual Household Latrines (IHHLs)</li>
<li>Community and Public Sanitation Facilities</li>
<li>Solid and Liquid Waste Management</li>
<li>Over 11 crore toilets built</li>
</ul>
<h3>SBM - Urban</h3>
<ul>
<li>Toilet construction and renovation</li>
<li>Door-to-door waste collection</li>
<li>Waste processing and disposal</li>
<li>ODF (Open Defecation Free) certification</li>
</ul>', `eligibility`='Rural: BPL households, SC/ST, women-headed households, persons with disabilities. Urban: All urban households.', `benefits`='₹12,000 for toilet construction (rural), ₹15,000 (urban), community toilet support, solid waste management.', `application_process`='1. Apply through Gram Panchayat (rural) or ULB (urban)\n2. Verification and approval\n3. Toilet construction\n4. ODF verification and certification', `required_documents`='Aadhaar Card, BPL certificate (for rural), Bank account details, House ownership proof' WHERE `slug`='swachh-bharat-mission';
UPDATE schemes SET `content`='<p>PM-KUSUM (Pradhan Mantri Kisan Urja Suraksha evam Utthaan Mahabhiyan) scheme provides solar energy solutions to farmers. It has three components.</p>
<h3>Components</h3>
<ul>
<li><strong>Component A:</strong> Standalone solar powered agriculture pumps (up to 7.5 HP)</li>
<li><strong>Component B:</strong> Solarization of existing agriculture pumps</li>
<li><strong>Component C:</strong> Installation of grid-connected solar power plants (500 kW to 2 MW)</li>
</ul>
<h3>Subsidy</h3>
<ul>
<li>Central subsidy: 30-60% depending on category</li>
<li>State subsidy: additional 30%</li>
<li>Farmer pays only 10-40%</li>
</ul>', `eligibility`='All farmers (individual or group), FPOs, cooperatives. Must have agriculture land and existing/bore well.', `benefits`='Solar pump at 10-40% cost, additional income from selling surplus power, reduced electricity bills.', `application_process`='1. Apply through state agriculture department or DISCOM\n2. Select component (A/B/C)\n3. Vendor selection and installation\n4. Subsidy disbursement', `required_documents`='Land records, Aadhaar Card, Bank account, Electricity connection details, Bore well details' WHERE `slug`='pm-kusum-solar-pump-scheme';
UPDATE schemes SET `content`='<p>Pradhan Mantri Vay Vandana Yojana is a pension scheme exclusively for senior citizens aged 60 years and above. It provides guaranteed pension with life insurance cover.</p>
<h3>Key Features</h3>
<ul>
<li>Assured pension: 8% per annum</li>
<li>Investment limit: ₹15 lakh</li>
<li>Pension payment: monthly, quarterly, half-yearly, or annually</li>
<li>Loan facility: up to 75% of deposit after 3 years</li>
<li>Maturity benefit: full deposit refund</li>
<li>Life insurance: proportionate to pension amount</li>
</ul>', `eligibility`='Senior citizens aged 60 years and above. Maximum investment ₹15 lakh.', `benefits`='8% assured pension, ₹15 lakh max investment, loan facility, life insurance cover.', `application_process`='1. Visit LIC office or online at licindia.in\n2. Fill PMVVY application form\n3. Submit KYC documents\n4. Investment amount\n5. Pension starts immediately', `required_documents`='Aadhaar Card, PAN Card, Bank account details, Passport size photos, Age proof' WHERE `slug`='pradhan-mantri-vay-vandana-yojana';
